    {
      "performanceId": "P-EXP",
      "earnedFromTask": "Zum Ziel 09029573-864f-40ca-bf8a-cee7bf6dcb73: eigener geprüfter Aufbau sowie zwei tatsächlich selbst erhobene Messreihen mit nachvollziehbaren Zeit-Ort-Daten.",
      "weight": 10,
      "completeOmissionMaximum": 14,
      "safeguardsAndLimits": "Direkt verlangt und eigenständig tragfähig. Jede vollständig fehlende eigene Datenreihe verliert 4,5 BE und unterschreitet damit bereits die Bestehensgrenze. Offen ausgewiesene Fremddaten sind keine Täuschungsfehlvorstellung; daran gezeigte Auswertungsmethoden bleiben bewertbar."
    },
    {
      "performanceId": "P-GRAPH",
      "earnedFromTask": "Zum selben Ziel: Messpunktdiagramme, nachvollziehbarer Mehrpunktausgleich und daraus bestimmte Beschleunigungen für A und B.",
      "weight": 6,
      "completeOmissionMaximum": 18,
      "safeguardsAndLimits": "Grafische Auswertung und g-Bestimmung bilden eine sachlich verbundene Leistung. Ein Steigungsdreieck auf einer Ausgleichsgeraden zählt. Quotientenmittel sind keine grafische Auswertung. Ein isolierter Rechenfehler kostet einmal 0,5 BE; eine beibehaltene falsche Steigungsdeutung entwertet die Gruppe."
    },
    {
      "performanceId": "P-LAW",
      "earnedFromTask": "Zum selben Ziel: reihenbezogene Zeit-Ort-Gesetze mit datenbasiert geprüften und angegebenen Anfangsbedingungen.",
      "weight": 5,
      "completeOmissionMaximum": 19,
      "safeguardsAndLimits": "Gleichwertige Schreibweisen und sinnvoll gedeutete Fitgleichungen zählen. Eine einzelne fehlende Prüfung bleibt eine Facettenlücke. Eine ausdrücklich beibehaltene falsche Vorzeichenregel entwertet dagegen die ganze Leistung. Bloße Fitparameter ohne entsprechendes Gesetz genügen nicht."
    }
  ],
  "coveredGoalReviews": [
    {
      "goalId": "09029573-864f-40ca-bf8a-cee7bf6dcb73",
      "mustShow": "Eigene reale Untersuchungen in A und B sowie insgesamt tragfähige Nachweise der grafischen Datenauswertung, der g-Bestimmung im Modell ohne Luftwiderstand und der Formulierung eines Zeit-Ort-Gesetzes mit Anfangsbedingungen.",
      "mayRemainOpen": "Einzelne Dokumentations- oder Auswertungsfacetten, beispielsweise die erneute datenbasierte Ruheprüfung in B, dürfen fehlen. Kleine Formfehler und sinnvoll begrenzte abweichende Messergebnisse sind tolerierbar. Eine präzise Bestimmung des Luftwiderstands oder ein statistisch abgesichertes Konfidenzintervall ist nicht verlangt.",
      "whyTolerable": "Das Ziel verlangt experimentelles Untersuchen und modellbezogenes Auswerten, keine vollständige metrologische Analyse. Die Gewichtung verhindert das Bestehen bei vollständig fehlender tragender Leistung, lässt aber begrenzte Lücken bei sonst erkennbarem Verständnis zu. Eine einzelne Prüfungsleistung belegt keine darüber hinausgehenden curricularen Kompetenzen."
    }
  ],
